use std::{fs, time::{SystemTime, UNIX_EPOCH}};
use super::SymphoniaDecoder;
fn wav_fixture() -> std::path::PathBuf { let mut bytes=Vec::new(); let samples:[i16;4]=[-12000,-1,1,12000]; let data_len=(samples.len()*2) as u32; bytes.extend_from_slice(b"RIFF");bytes.extend_from_slice(&(36+data_len).to_le_bytes());bytes.extend_from_slice(b"WAVEfmt ");bytes.extend_from_slice(&16u32.to_le_bytes());bytes.extend_from_slice(&1u16.to_le_bytes());bytes.extend_from_slice(&1u16.to_le_bytes());bytes.extend_from_slice(&8000u32.to_le_bytes());bytes.extend_from_slice(&16000u32.to_le_bytes());bytes.extend_from_slice(&2u16.to_le_bytes());bytes.extend_from_slice(&16u16.to_le_bytes());bytes.extend_from_slice(b"data");bytes.extend_from_slice(&data_len.to_le_bytes());for sample in samples{bytes.extend_from_slice(&sample.to_le_bytes());}let nonce=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();let path=std::env::temp_dir().join(format!("timbre-audio-{nonce}.wav"));fs::write(&path,bytes).unwrap();path }
#[test] fn decodes_wav_and_reaches_end_of_stream(){let path=wav_fixture();let mut decoder=SymphoniaDecoder::open(&path).unwrap();assert_eq!(decoder.duration_seconds(),Some(0.0005));assert_eq!(decoder.audio_format().sample_rate,8000);assert_eq!(decoder.audio_format().channels,1);let mut all=Vec::new();while let Some(chunk)=decoder.next_chunk().unwrap(){all.extend(chunk.samples);}assert_eq!(all,[-12000,-1,1,12000]);assert!(decoder.next_chunk().unwrap().is_none());let _=fs::remove_file(path);}
#[test] fn rejects_invalid_seek_positions(){let path=wav_fixture();let mut decoder=SymphoniaDecoder::open(&path).unwrap();assert!(decoder.seek_seconds(-1.0).is_err());assert!(decoder.seek_seconds(f64::NAN).is_err());let _=fs::remove_file(path);}
